import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"BMC 详解","description":"","frontmatter":{"title":"BMC 详解","order":56},"headers":[],"relativePath":"kernel/equip/motherboard/bmc.md","filePath":"kernel/equip/motherboard/bmc.md"}`),a={name:`kernel/equip/motherboard/bmc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="bmc-主板管理器" tabindex="-1">BMC 主板管理器 <a class="header-anchor" href="#bmc-主板管理器" aria-label="Permalink to “BMC 主板管理器”">​</a></h1><p>BMC（Baseboard Management Controller）是服务器主板上一个独立的小型计算机——有自己的 ARM 处理器、内存、存储、网卡和固件，通过 I2C、SMBus、PCIe 与主板各组件相连。只要电源线插着，BMC 就保持在线——主 CPU 关机、操作系统崩溃、甚至主板故障都不影响它工作。这个&quot;独立于主系统的第二台计算机&quot;是服务器与消费级主板最本质的硬件差异。</p><h2 id="硬件架构" tabindex="-1">硬件架构 <a class="header-anchor" href="#硬件架构" aria-label="Permalink to “硬件架构”">​</a></h2><p>主流的 BMC 芯片是 ASPEED 的 AST2500（2016）和 AST2600（2019）系列。AST2500 集成 800MHz ARM11 处理器、DDR3/DDR4 内存控制器、2D 图形引擎（用于 KVM 视频输出）；AST2600 升级为 1.2GHz 双核 Cortex-A7 和 4 核图形引擎。除了 ASPEED，服务器大厂有自研 BMC——华为的 iBMC、HPE 的 iLO 芯片、Dell 的 iDRAC 芯片（基于自有或定制硅片）。</p><p>BMC 与主系统的连接是理解其能力边界的关键：</p><ul><li><strong>I2C/SMBus</strong>：连接温度传感器、风扇控制器、电压监控芯片——BMC 通过轮询这些总线采集主板健康数据</li><li><strong>PCIe 低速链路</strong>：连接视频捕获芯片（VGA 信号捕获用于远程 KVM）和 USB 控制器（虚拟键鼠注入）</li><li><strong>NC-SI（Network Controller Sideband Interface）</strong>：与主板网卡共享物理网口——BMC 通过 NC-SI 借用主网口的流量通道，无需专用管理网口</li><li><strong>UART</strong>：连接主板串口，实现 Serial-over-LAN</li></ul><p>BMC 的电源来自待机电路（standby rail）——主系统关机后依然供电。这意味着 BMC 的功耗（2-5W）是服务器关机时的持续开销。</p><h2 id="固件与协议栈" tabindex="-1">固件与协议栈 <a class="header-anchor" href="#固件与协议栈" aria-label="Permalink to “固件与协议栈”">​</a></h2><p>BMC 固件是一个完整的嵌入式 Linux 系统。主流选择是 OpenBMC（开源，由 IBM/Meta/谷歌推动）和 AMI MegaRAC（商业闭源，ASPEED 生态的默认选项）。SuperMicro/HPE/Dell 在两者之上叠加自有的 Web UI 和管理功能。</p><p>对外协议分为两代。<strong>IPMI</strong>（Intelligent Platform Management Interface）是 1998 年的标准：基于 UDP 623 端口的二进制协议，定义传感器读取（SDR，Sensor Data Record）、事件日志（SEL，System Event Log）、电源控制、LAN 串口重定向等命令。IPMI 的设计年代决定了它的粗糙——明文认证（IPMI 1.5）、固定格式、安全性差。</p><p><strong>Redfish</strong> 是 DMTF 2015 年发布的现代替代：基于 REST API + JSON + OData，通过 HTTPS 访问。资源模型直观（<code>/redfish/v1/Systems/1</code> 代表服务器，<code>/redfish/v1/Chassis/1/Thermal</code> 代表温度数据），支持标准的认证和 TLS。现代 BMC 同时暴露两个接口，但新工具链（Ansible、Terraform 的服务器插件、云厂商的裸机 API）全部面向 Redfish。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># IPMI 命令行：读取 CPU 温度、风扇转速</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipmitool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sensor</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;CPU|FAN&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipmitool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                        # 事件日志</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipmitool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chassis</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> power</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">            # 电源状态</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Redfish 的 curl 等价物</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin:password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://bmc-ip/redfish/v1/Chassis/1/Thermal</span></span></code></pre></div><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><p><strong>带外管理</strong>（Out-of-Band）是 BMC 的第一价值。操作系统内的一切管理工具（SSH、远程桌面）都依赖主系统存活——主系统崩溃时它们全部失效。BMC 的独立通道在&quot;操作系统都进不去&quot;时依然可用：远程开机/关机/重启、BIOS 设置修改、固件更新。服务器机房&quot;无人值守&quot;的运维模式完全建立在这个能力上。</p><p><strong>远程 KVM</strong>：BMC 的图形引擎捕获主板的 VGA 输出，压缩后通过管理网络传输，同时把远程键鼠输入注入为 USB 设备。效果是&quot;物理坐在机房里&quot;的完整替代——从开机自检到 BIOS 配置到操作系统安装，全程远程操作。</p><p><strong>虚拟介质</strong>：把远程的 ISO/IMG 文件挂载为服务器的虚拟光驱/软驱/U 盘。远程装机的标准流程：挂载安装镜像 → 设置一次性启动项 → 重启 → KVM 中完成安装。</p><p><strong>传感器与告警</strong>：BMC 持续轮询温度（CPU 核心、内存、VRM、进风口）、电压、风扇转速、电源状态。超过阈值触发事件（写入 SEL 日志，可配置 SNMP trap 或邮件告警）。风扇控制策略由 BMC 的 PID 控制器执行——这也解释了为什么服务器主板的风扇不经过 BIOS 控制。</p><h2 id="安全面" tabindex="-1">安全面 <a class="header-anchor" href="#安全面" aria-label="Permalink to “安全面”">​</a></h2><p>BMC 是服务器安全中被攻击最频繁的目标之一——它权限极高（可以控制电源、注入键鼠、读取所有传感器）且永远在线。历史漏洞（如 2018 年的 IPMI 密码哈希泄露、多个固件 RCE）证明：BMC 的 Web 界面、IPMI 明文协议、固件更新通道都是攻击面。</p><p>工程上的防御实践：管理网络与业务网络物理隔离（BMC 网口接独立交换机/VLAN）；禁用 IPMI 只保留 Redfish（HTTPS）；定期更新 BMC 固件（漏洞修复频率高于 BIOS）；修改默认密码（出厂 <code>ADMIN/ADMIN</code> 是许多安全事件的起点）；限制 BMC 的互联网暴露（Shodan 上可以搜到大量暴露的 BMC 控制台）。</p><h2 id="个人装机的意义" tabindex="-1">个人装机的意义 <a class="header-anchor" href="#个人装机的意义" aria-label="Permalink to “个人装机的意义”">​</a></h2><p>个人 EPYC/Xeon 装机获得的 BMC 能力，是消费级主板无法提供的：远程装机（虚拟介质 + KVM）、崩溃后的远程救援（系统 hang 时 reset）、无显示器的服务器管理（全程 Serial-over-LAN）。这正是 <a href="./epyc">EPYC 装机</a> 和 <a href="./xeon">Xeon 装机</a> 文章中反复出现 BMC 配置话题的原因——首次开机后风扇全速运转需要登录 BMC 调整风扇曲线、默认密码需要修改、NC-SI 共享网口需要配置。</p><p>一个实用的装机习惯：新主板到手先通过 <code>ipmitool lan print</code> 确认 BMC IP（或配置静态 IP），然后立即更新固件、修改密码、配置风扇曲线——这三件事做完，服务器才算&quot;可以进机房&quot;。</p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};